const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function supported(f){return f.allowedValues?.length||['string','number','user'].includes(f.schema?.type)||f.schema?.type==='array'&&f.schema?.items==='string'||(f.fieldId||f.key)==='parent';}
function control(f){const id=f.fieldId||f.key,required=f.required&&!f.hasDefaultValue?'required':'',s=f.schema||{},attrs=`name="${esc(id)}" ${required}`;let input;if(f.allowedValues?.length){input=`<select ${attrs} ${s.type==='array'?'multiple':''}><option value="">${required?'Select…':'Use Jira default'}</option>${f.allowedValues.map(v=>`<option value="${esc(v.id??v.value??v.name)}">${esc(v.name??v.value??v.id)}</option>`).join('')}</select>`;}else if(id==='description'||s.custom?.endsWith(':textarea'))input=`<textarea ${attrs}></textarea>`;else input=`<input ${attrs} type="${s.type==='number'?'number':'text'}" ${s.type==='number'?'step="any"':''} ${id==='summary'?'maxlength="255"':''}>`;return `<label class="field">${esc(f.name)}${required?' *':''}${input}${s.type==='user'?'<small>Enter an Atlassian account ID (Cloud) or username (Data Center). Leave blank to use Jira’s default.</small>':s.type==='array'&&!f.allowedValues?.length?'<small>Separate values with commas.</small>':''}</label>`;}
export function mountTicketCreation(root){const button=document.createElement('button');button.className='primary';button.textContent='+ Create ticket';root.querySelector('.heading').append(button);button.onclick=async()=>{const connectionForm=root.querySelector('#jira-form');if(!connectionForm.reportValidity())return;let config=Object.fromEntries(new FormData(connectionForm));if(!config.project.trim()){connectionForm.elements.project.focus();return;}const dialog=document.createElement('dialog');document.body.append(dialog);let meta=[],types=[],links=[],draft=null,working=false;
 const api=async(action,data={})=>{const r=await fetch('/api/jira/tickets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,connection:config,...data})});let result;try{result=await r.json();}catch{throw Error('Server response unavailable. If you submitted creation, check Jira before trying again.');}if(!r.ok)throw Error(result.error||'Jira request failed.');return result;};
 const close=()=>{if(working)return;dialog.close();};dialog.addEventListener('cancel',e=>{if(working)e.preventDefault();});dialog.addEventListener('close',()=>{config.token='';connectionForm.elements.token.value='';dialog.remove();});
 dialog.innerHTML='<h2>Create Jira ticket</h2><p role="status">Loading project issue types…</p><div class="dialog-actions"><button type="button" id="ticket-close">Cancel</button></div>';dialog.showModal();dialog.querySelector('#ticket-close').onclick=close;
 try{working=true;types=(await api('types')).types;try{links=(await api('links')).issueLinkTypes||[];}catch{links=[];}if(!dialog.isConnected)return;dialog.innerHTML=`<h2>Create Jira ticket</h2><p>${esc(config.url)} · ${esc(config.project)}</p><form id="ticket-form" style="margin-top:18px"><label class="field">Issue type<select id="create-type" required><option value="">Select issue type…</option>${types.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></label><div id="ticket-fields" style="display:grid;gap:14px"></div><details><summary>Link to an existing ticket (optional)</summary><label class="field">Link type<select id="ticket-link-type"><option value="">Select link…</option>${links.map(l=>`<option value="${esc(l.name)}">${esc(l.outward)} (${esc(l.name)})</option>`).join('')}</select></label><label class="field">Target ticket key<input id="ticket-link-key" placeholder="SCRUM-123"></label><small>The new ticket is the source of this outward link. Use Parent above for hierarchy relationships.</small></details><p id="ticket-error" class="error" role="alert"></p><div class="dialog-actions"><button type="button" id="ticket-close">Cancel</button><button id="ticket-review" class="primary" disabled>Review ticket</button></div></form><div id="ticket-confirm" hidden></div>`;
 const form=dialog.querySelector('#ticket-form'),error=dialog.querySelector('#ticket-error'),review=dialog.querySelector('#ticket-review'),selector=dialog.querySelector('#create-type');dialog.querySelector('#ticket-close').onclick=close;
 selector.onchange=async()=>{if(working)return;if(!selector.value){review.disabled=true;dialog.querySelector('#ticket-fields').innerHTML='';return;}working=true;selector.disabled=true;review.disabled=true;error.textContent='';dialog.querySelector('#ticket-fields').innerHTML='Loading fields…';try{meta=(await api('fields',{type:selector.value})).fields;const shown=meta.filter(f=>!['project','issuetype'].includes(f.fieldId||f.key));const unsupported=shown.filter(f=>!supported(f)&&f.required&&!f.hasDefaultValue);dialog.querySelector('#ticket-fields').innerHTML=shown.filter(supported).map(control).join('');if(unsupported.length)error.textContent='These required fields need Jira’s native editor: '+unsupported.map(f=>f.name).join(', ');else review.disabled=false;}catch(e){error.textContent=e.message;dialog.querySelector('#ticket-fields').innerHTML='';}finally{working=false;selector.disabled=false;}};
 form.onsubmit=async e=>{e.preventDefault();if(working)return;working=true;review.disabled=true;error.textContent='';try{const values={};for(const [key,value] of new FormData(form)){const f=meta.find(f=>(f.fieldId||f.key)===key);if(f?.schema?.type==='array'&&f.allowedValues?.length){(values[key]||=[]).push(value);}else values[key]=value;}draft=await api('prepare',{type:selector.value,values,link:{key:dialog.querySelector('#ticket-link-key').value.trim(),type:dialog.querySelector('#ticket-link-type').value}});form.hidden=true;const confirm=dialog.querySelector('#ticket-confirm');confirm.hidden=false;confirm.innerHTML=`<h3 style="margin-top:18px">Review before creating</h3><p>${esc(draft.project)} · ${esc(draft.type)}</p><dl>${Object.entries(values).filter(([,v])=>v?.length).map(([key,v])=>`<dt style="font-weight:600;margin-top:12px">${esc(meta.find(f=>(f.fieldId||f.key)===key)?.name||key)}</dt><dd style="margin:0;white-space:pre-wrap">${esc(Array.isArray(v)?v.join(', '):v)}</dd>`).join('')}</dl>${draft.link?`<p>New ticket → ${esc(draft.link.type)} → ${esc(draft.link.key)}</p>`:''}<p>This will create a real ticket in Jira.</p><p id="create-result" role="status"></p><div class="dialog-actions"><button type="button" id="ticket-back">Back</button><button type="button" id="ticket-send" class="primary">Create in Jira</button></div>`;confirm.querySelector('#ticket-back').onclick=()=>{if(working)return;confirm.hidden=true;form.hidden=false;};confirm.querySelector('#ticket-send').onclick=async()=>{if(working)return;working=true;confirm.querySelectorAll('button').forEach(b=>b.disabled=true);const result=confirm.querySelector('#create-result');result.textContent='Creating ticket…';try{const created=await api('create',{id:draft.id});result.innerHTML=`Created <a href="${esc(created.url)}" target="_blank" rel="noopener noreferrer">${esc(created.key)} ↗</a>${created.warning?`<p class="error">${esc(created.warning)}</p>`:''}<p>Refresh the Jira import to include this ticket in your inventory.</p>`;confirm.querySelector('.dialog-actions').innerHTML='<button type="button" id="ticket-done">Done</button>';confirm.querySelector('#ticket-done').onclick=close;}catch(e){result.textContent=e.message;confirm.querySelector('.dialog-actions').innerHTML='<button type="button" id="ticket-done">Close</button>';confirm.querySelector('#ticket-done').onclick=close;}finally{working=false;}};}catch(e){error.textContent=e.message;}finally{working=false;review.disabled=false;}};
 }catch(e){dialog.innerHTML=`<h2>Unable to load Jira ticket types</h2><p class="error">${esc(e.message)}</p><div class="dialog-actions"><button id="ticket-close">Close</button></div>`;dialog.querySelector('#ticket-close').onclick=close;}finally{working=false;}};}

